import { readFile } from "node:fs/promises";
import { join } from "node:path";

let build: Promise<string | null> | undefined;

// Railway sets a deployment ID shared by all replicas. Standalone installs
// outside Railway can use the ID generated by next build.
export function appRelease() {
  if (process.env.RAILWAY_DEPLOYMENT_ID) return Promise.resolve(process.env.RAILWAY_DEPLOYMENT_ID);
  if (process.env.NODE_ENV !== "production") return Promise.resolve(null);
  return build ??= readFile(join(process.cwd(), ".next", "BUILD_ID"), "utf8")
    .then(value => value.trim() || null).catch(() => null);
}
